import{_ as n,o as a,c as s,a5 as t}from"./chunks/framework.bIR-4glx.js";const u=JSON.parse('{"title":"Startup Experiment Card: Assumptions, Evidence, Costs, and Decisions","description":"A reusable record for a business experiment, with assumptions, alternatives, counterevidence, manual pilots, effort limits, and a complete hypothetical example of a bounded conclusion.","frontmatter":{"title":"Startup Experiment Card: Assumptions, Evidence, Costs, and Decisions","description":"A reusable record for a business experiment, with assumptions, alternatives, counterevidence, manual pilots, effort limits, and a complete hypothetical example of a bounded conclusion.","updated":"2026-09-19T00:00:00.000Z","worksheetDownload":{"url":"/downloads/worksheets/startup-experiment.en.md","name":"startup-experiment.en.md"}},"headers":[],"relativePath":"en/templates/startup-experiment.md","filePath":"en/templates/startup-experiment.md","lastUpdated":1789776000000}'),i={name:"en/templates/startup-experiment.md"};function o(r,e,p,d,l,c){return a(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="startup-experiment-card" tabindex="-1">Startup Experiment Card <a class="header-anchor" href="#startup-experiment-card" aria-label="Permalink to &quot;Startup Experiment Card&quot;">​</a></h1><p>Use this card to answer a specific question: “Is the next investment of effort worthwhile?” Write the assumption, scope, and decision conditions before approaching users. This is a working template suggested by the guide, not a market validation standard. The two-week period is adjustable, and the examples are entirely hypothetical.</p><p>Test one main assumption at a time. Record questions outside the scope without quietly expanding the card into a complete business plan. For the method, see <a href="./../threads/practice/customer-discovery">From a Real Problem to First Customers</a>. For working time and operational observations, see <a href="./../threads/practice/sustainable-business">A Sustainable Small Business</a>.</p><h2 id="copy-the-blank-card" tabindex="-1">Copy the Blank Card <a class="header-anchor" href="#copy-the-blank-card" aria-label="Permalink to &quot;Copy the Blank Card&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Experiment name / identifier:</span></span>
<span class="line"><span>Owner / start and end dates:</span></span>
<span class="line"><span>The next decision this experiment will inform:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[COMPLETE BEFORE STARTING]</span></span>
<span class="line"><span>Target users and specific task:</span></span>
<span class="line"><span>User / adoption decision-maker / payer:</span></span>
<span class="line"><span>Evidence that the task occurred recently:</span></span>
<span class="line"><span>Current alternatives and their costs:</span></span>
<span class="line"><span>Main assumption (one statement that could be disproved):</span></span>
<span class="line"><span>Strongest counterexample or alternative explanation:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Contact channel / eligibility conditions:</span></span>
<span class="line"><span>Planned invitations / interviews / pilots:</span></span>
<span class="line"><span>Possible recruitment bias (such as friends or volunteers):</span></span>
<span class="line"><span>Pilot deliverables / explicit exclusions:</span></span>
<span class="line"><span>Price / revision scope / delivery and acceptance method:</span></span>
<span class="line"><span>What people do and what tools do:</span></span>
<span class="line"><span>Material permissions / recording consent / retention and deletion:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Old-process baseline (quality, time on both sides, spending):</span></span>
<span class="line"><span>Behavioral evidence to record and where it will be stored:</span></span>
<span class="line"><span>Advance conditions for continuing:</span></span>
<span class="line"><span>Advance conditions for adjusting:</span></span>
<span class="line"><span>Advance conditions for stopping or pausing:</span></span>
<span class="line"><span>Time limit / cash spending limit / deadline:</span></span>
<span class="line"><span>Who can stop the experiment / how unfinished commitments are handled:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[COMPLETE AFTER ENDING]</span></span>
<span class="line"><span>Actual invitations / responses / interviews / quotes / payments / acceptances:</span></span>
<span class="line"><span>User behavior (anonymous ID + date + evidence summary):</span></span>
<span class="line"><span>Counterexamples / refusals / withdrawals and reasons:</span></span>
<span class="line"><span>Actual quotes / payments received / refunds / spending:</span></span>
<span class="line"><span>All hours (recruitment, communication, preparation, production, revisions, support):</span></span>
<span class="line"><span>Old/new process comparison and conditions that remain incomparable:</span></span>
<span class="line"><span>Departures from the original plan and why:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>What the evidence supports / what it does not support:</span></span>
<span class="line"><span>Decision: continue / adjust / stop / insufficient evidence, pause</span></span>
<span class="line"><span>Reason for the decision:</span></span>
<span class="line"><span>Unfinished commitments and responsible person:</span></span>
<span class="line"><span>The single main change in the next round:</span></span>
<span class="line"><span>What new fact would change this judgment:</span></span>
<span class="line"><span>Next review date:</span></span></code></pre></div><p>Each field can be brief. An evidence summary might say, “User A showed de-identified examples of two tasks from last week.” Do not paste complete customer materials into a public repository. Keep only the anonymous summary needed to verify payment; private contact details and transaction receipts belong in an appropriately restricted location.</p><h2 id="worked-example-organizing-product-information" tabindex="-1">Worked Example: Organizing Product Information <a class="header-anchor" href="#worked-example-organizing-product-information" aria-label="Permalink to &quot;Worked Example: Organizing Product Information&quot;">​</a></h2><p>This example tests only whether shop owners will pay for a limited information-organizing service and whether delivery can stay within a time allowance. It is not a plan to launch an AI product. All people, behavior, and numbers below are fictional illustrations.</p><table tabindex="0"><thead><tr><th>Field</th><th>Example entry</th></tr></thead><tbody><tr><td>Period and owner</td><td>Two weeks, with the pilot owner recording observations and deciding</td></tr><tr><td>Users and task</td><td>Shop owners who maintain product information themselves and updated at least two batches in the previous two weeks</td></tr><tr><td>Roles</td><td>The owner uses, decides, and pays; only this arrangement is eligible</td></tr><tr><td>Current approach</td><td>Copy fields from an existing spreadsheet and manually check specifications</td></tr><tr><td>Main assumption</td><td>Someone will pay 200 yuan to have up to 20 confirmed product entries organized into a publishing draft</td></tr><tr><td>Counterexample</td><td>An existing template is already fast enough; communicating with a provider adds time</td></tr><tr><td>Recruitment and bias</td><td>Invite 10 people and aim for 6 interviews; some are acquaintances, so the results do not directly represent strangers</td></tr><tr><td>Pilot scope</td><td>At most 2 orders; one draft plus open questions, with one round of revisions within scope; no publishing and no new product facts</td></tr><tr><td>Materials and disclosure</td><td>Use only information the owner confirms may be used; explain manual work and tool assistance, with no external sharing without permission</td></tr><tr><td>Acceptance</td><td>Agreed fields are complete for up to 20 entries, unresolved items are identifiable, and the customer confirms receipt after checking</td></tr><tr><td>Effort limits</td><td>12 hours for the whole round and 100 yuan of cash spending; these are choices for this example only</td></tr><tr><td>Continue conditions</td><td>At least 3 of 6 interviews show a recent recurring task; at least 2 people pay 200 yuan and complete acceptance, with communication through support taking no more than 2 hours per order</td></tr><tr><td>Adjust conditions</td><td>There is payment and acceptance, but delivery time exceeds the allowance; narrow the next scope or improve input requirements</td></tr><tr><td>Stop or pause conditions</td><td>Insufficient evidence by the deadline, the total effort limit is reached, or necessary material permissions are unavailable</td></tr></tbody></table><p>Anchor the baseline in a particular task too. Suppose the two pilot users supply timing summaries of their old process: 90 and 60 minutes respectively. In the new process, user preparation, communication, and review take 30 and 70 minutes, while provider work takes 90 and 210 minutes. There is one signal of user time saved and one counterexample where user time increases. Do not showcase only the first user.</p><h2 id="example-results-and-interpretation" tabindex="-1">Example Results and Interpretation <a class="header-anchor" href="#example-results-and-interpretation" aria-label="Permalink to &quot;Example Results and Interpretation&quot;">​</a></h2><p>Suppose 10 people were invited, 8 responded, and 6 completed interviews. Four showed recent recurring tasks. Three received the same quote; two paid and accepted delivery, while one declined because the existing template was sufficient. Payments totaled 400 yuan, with no refunds and 40 yuan of cash spending. All recruitment and delivery work took 11 hours. Provider work on the two orders took 1.5 and 3.5 hours, with 6 hours for other work: still 11 hours in total.</p><p>The second order involved inconsistent input formats and extra checking. The user&#39;s own preparation and review also took longer than the old process. Although payment and acceptance counts met the conditions, the per-order time condition did not. The decision is therefore <strong>adjust</strong>. The next round will accept only materials that follow the input template, keeping the price and quantity limit unchanged, and test working time again. That proposed improvement is still an assumption; it cannot already be described as a solved problem.</p><p>This round supports “These two users accepted a paid pilot under these conditions.” It does not establish regular repeat purchases, acquisition costs through unfamiliar channels, or sustainable profit. <code>400 - 40 = 360 yuan</code> is only the remainder after the listed cash spending. It excludes eleven hours of labor and other costs, so it is not a claim of 360 yuan in profit.</p><p>If only two interviews were completed, record “The planned evidence volume was not reached; judgment is paused,” explaining whether recruitment was difficult or too little effort was available. Do not lower the threshold to two after seeing the results and claim success. If a plan must change, retain the original version, change date, and reason, and apply new conditions to the next round.</p><h2 id="finish-with-a-checkable-conclusion" tabindex="-1">Finish with a Checkable Conclusion <a class="header-anchor" href="#finish-with-a-checkable-conclusion" aria-label="Permalink to &quot;Finish with a Checkable Conclusion&quot;">​</a></h2><blockquote><p>Within two weeks and limits of twelve hours and 100 yuan of spending, we observed two paid and accepted deliveries, but one exceeded its delivery-time allowance. We will narrow the accepted input format and run another round. We are not yet increasing order volume.</p></blockquote><p>For a shorter English update:</p><blockquote><p>Two customers paid for and accepted the pilot, but one delivery exceeded our time limit. We will test a stricter input format before taking more orders. Repeat demand and sustainable costs remain unproven.</p></blockquote>`,19)])])}const m=n(i,[["render",o]]);export{u as __pageData,m as default};
